using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Drawing;using System.Globalization;using Newtonsoft.Json.Linq;
namespace JonsboStudio {
 sealed class ThemeDocument {
  public string Path,Folder,Background;public JObject Json;public bool Video;public string Warning="";
  public string Name{get{return (string)Json["Name"]??"Untitled";}}
  public int Width{get{return Math.Max(16,Math.Min(3840,(int?)Json["Width"]??1920));}}
  public int Height{get{return Math.Max(16,Math.Min(2400,(int?)Json["Height"]??462));}}
  public string BackgroundFit{get{string fit=(string)Json["BackgroundFit"];return fit=="contain"||fit=="cover"||fit=="fill"||fit=="region"?fit:((int?)Json["Type"]==1?"fill":"cover");}}
  public int BackgroundRotation{get{return Math.Max(0,Math.Min(360,(int?)Json["BackgroundRotation"]??0));}}
  public RectangleF BackgroundRegion{get{var region=Json["BackgroundRegion"] as JObject;float x=Math.Max(0,Math.Min(.99f,region==null?0:(float?)region["x"]??0)),y=Math.Max(0,Math.Min(.99f,region==null?0:(float?)region["y"]??0));float width=Math.Max(.01f,Math.Min(1-x,region==null?1:(float?)region["width"]??1)),height=Math.Max(.01f,Math.Min(1-y,region==null?1:(float?)region["height"]??1));return new RectangleF(x,y,width,height);}}
  public JArray Texts{get{return Json["DisplayTexts"] as JArray??new JArray();}}
  public JArray Images{get{return Json["DisplayImages"] as JArray??new JArray();}}
  public static JObject Blank(string name,int width,int height){return new JObject{{"IsDefault",false},{"Type",0},{"Name",name},{"Width",width},{"Height",height},{"BackgroundFit","cover"},{"BackgroundRotation",0},{"FillMode",0},{"CropArea","0, 0, 0, 0"},{"DisplayDirection",0},{"FontDirection",0},{"BackgroundImage",null},{"BackgroundVideoFile",null},{"DisplayTexts",new JArray()},{"DisplayImages",new JArray()},{"TouchPoints",new JArray()},{"ShutDownCancelPoint",new JObject{{"TPType",0},{"Content",""},{"X1",0},{"X2",0},{"Y1",0},{"Y2",0}}},{"IsTouch",0},{"IsApp",0},{"Isup",true}};}
  public static ThemeDocument Load(string path){
   if(new FileInfo(path).Length>32*1024*1024)throw new InvalidDataException("Theme JSON exceeds 32 MB.");
   var theme=new ThemeDocument{Path=System.IO.Path.GetFullPath(path),Folder=System.IO.Path.GetDirectoryName(System.IO.Path.GetFullPath(path)),Json=JObject.Parse(File.ReadAllText(path))};
   foreach(string field in new[]{"DisplayTexts","DisplayImages","TouchPoints"})if(!(theme.Json[field] is JArray))theme.Json[field]=new JArray();
   string video=theme.Resolve((string)theme.Json["BackgroundVideoFile"]),image=theme.Resolve((string)theme.Json["BackgroundImage"]);
   if(!File.Exists(video))video=theme.FindFile("back.mp4");if(!File.Exists(image))image=theme.FindFile("back.png");
   theme.Video=File.Exists(video);theme.Background=theme.Video?video:File.Exists(image)?image:"";
   if(theme.Video)theme.Json["BackgroundVideoFile"]=theme.Background;else if(theme.Background.Length>0)theme.Json["BackgroundImage"]=theme.Background;
   foreach(JObject layer in theme.Images.OfType<JObject>()){string resolved=theme.Resolve((string)layer["Image"]??(string)layer["ImageFileName"]);if(File.Exists(resolved))layer["Image"]=resolved;}
   string layout=theme.FindFile("Setting.txt");if((int?)theme.Json["Type"]==1&&File.Exists(layout)){theme.ParseLayout(File.ReadAllLines(layout));}
   return theme;
  }
  public string FindFile(string name){string path=System.IO.Path.Combine(Folder,name);if(File.Exists(path))return path;return Directory.GetFiles(Folder,"*",SearchOption.AllDirectories).FirstOrDefault(x=>string.Equals(System.IO.Path.GetFileName(x),name,StringComparison.OrdinalIgnoreCase))??"";}
  public string Resolve(string value){if(string.IsNullOrWhiteSpace(value))return "";try{if(value.StartsWith("file:",StringComparison.OrdinalIgnoreCase))value=new Uri(value).LocalPath;if(File.Exists(value))return System.IO.Path.GetFullPath(value);string local=System.IO.Path.Combine(Folder,System.IO.Path.GetFileName(value));if(File.Exists(local))return local;return FindFile(System.IO.Path.GetFileName(value));}catch{return "";}}
  static double Number(Dictionary<string,string> values,string key,double fallback=0){string value;double number;return values.TryGetValue(key,out value)&&double.TryParse(value,NumberStyles.Any,CultureInfo.InvariantCulture,out number)?number:fallback;}
  void ParseLayout(string[] lines){
   bool parseTexts=Texts.Count==0,parseImages=Images.Count==0,parseShapes=(Json["EnhancedShapes"] as JArray??new JArray()).Count==0,unsupported=false;
   var texts=new JArray();var images=new JArray();var shapes=new JArray();
   foreach(string raw in lines){int colon=raw.IndexOf(':');if(colon<0)continue;string kind=raw.Substring(0,colon);var values=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string token in raw.Substring(colon+1).Split(',')){int at=token.IndexOf('@');if(at>0)values[token.Substring(0,at)]=token.Substring(at+1);}Func<string,string,string> get=(key,fallback)=>values.ContainsKey(key)?values[key]:fallback;
    if(kind=="Text"){if(parseTexts)texts.Add(new JObject{{"Id",Guid.NewGuid().ToString()},{"Left",Number(values,"x")},{"Top",Number(values,"y")},{"ZIndex",Number(values,"z")},{"TextType",get("IsDefaultText","false")=="true"?"DIYTextList":get("data","DIYTextList")},{"Text",get("data","")},{"Color",get("Foreground","White")},{"FontName",get("FontFamily","Segoe UI").TrimStart('#')},{"FontSize",Number(values,"FontSize",24)},{"Bold",false},{"Italic",false},{"Underline",false},{"IsShowTitle",false},{"Unit",get("unit","")}});}
    else if(kind=="BorderLine"){if(parseShapes)shapes.Add(new JObject{{"kind","rectangle"},{"x",Number(values,"x")},{"y",Number(values,"y")},{"width",Number(values,"maxwidth",100)},{"height",Number(values,"maxheight",2)},{"color",get("Fill","#444444")},{"z",Number(values,"z")}});}
    else if(System.Text.RegularExpressions.Regex.IsMatch(kind,@"\.(png|jpe?g|bmp|gif)$",System.Text.RegularExpressions.RegexOptions.IgnoreCase)){if(parseImages){string source=Resolve(kind);if(File.Exists(source))images.Add(new JObject{{"Left",Number(values,"x")},{"Top",Number(values,"y")},{"ZIndex",Number(values,"z")},{"Width",Number(values,"width",Width)},{"Height",Number(values,"height",Height)},{"Image",source},{"ImageFileName",System.IO.Path.GetFileName(source)}});else unsupported=true;}}
    else if(kind!="name"&&kind!="width"&&kind!="height")unsupported=true;
   }
   if(parseTexts)Json["DisplayTexts"]=texts;if(parseImages)Json["DisplayImages"]=images;if(parseShapes)Json["EnhancedShapes"]=shapes;
   Warning=unsupported?"Some native layout elements could not be rendered. Text, image and basic shape layers are available.":"";
  }
  public JObject ForEditor(){var copy=(JObject)Json.DeepClone();copy["BackgroundFit"]=BackgroundFit;copy["BackgroundRotation"]=BackgroundRotation;copy["backgroundUrl"]=AppPaths.AssetUrl(Background);copy["backgroundIsVideo"]=Video;copy["filePath"]=Path;copy["warning"]=Warning;foreach(JObject image in ((JArray)copy["DisplayImages"]).OfType<JObject>())image["url"]=AppPaths.AssetUrl((string)image["Image"]);var fontFiles=new JArray();string fontFolder=System.IO.Path.Combine(Folder,"font");if(Directory.Exists(fontFolder))foreach(string file in Directory.GetFiles(fontFolder,"*.ttf"))fontFiles.Add(new JObject{{"name",System.IO.Path.GetFileNameWithoutExtension(file).Replace('_',' ')},{"url",AppPaths.AssetUrl(file)}});copy["fontAssets"]=fontFiles;return copy;}
  public ThemeDocument FitTo(int width,int height){var copy=new ThemeDocument{Path=Path,Folder=Folder,Background=Background,Video=Video,Json=(JObject)Json.DeepClone(),Warning=Warning};double scale=Math.Min(width/(double)Width,height/(double)Height),left=(width-Width*scale)/2,top=(height-Height*scale)/2;foreach(JObject layer in copy.Texts.OfType<JObject>()){layer["Left"]=((double?)layer["Left"]??0)*scale+left;layer["Top"]=((double?)layer["Top"]??0)*scale+top;layer["FontSize"]=((double?)layer["FontSize"]??32)*scale;}foreach(JObject layer in copy.Images.OfType<JObject>()){layer["Left"]=((double?)layer["Left"]??0)*scale+left;layer["Top"]=((double?)layer["Top"]??0)*scale+top;layer["Width"]=((double?)layer["Width"]??60)*scale;layer["Height"]=((double?)layer["Height"]??60)*scale;}foreach(JObject layer in (copy.Json["EnhancedShapes"] as JArray??new JArray()).OfType<JObject>()){layer["x"]=((double?)layer["x"]??0)*scale+left;layer["y"]=((double?)layer["y"]??0)*scale+top;layer["width"]=((double?)layer["width"]??100)*scale;layer["height"]=((double?)layer["height"]??2)*scale;}copy.Json["Width"]=width;copy.Json["Height"]=height;return copy;}
  public static Color ParseColor(string value){try{if(string.IsNullOrEmpty(value))return Color.White;if(value.StartsWith("#")){if(value.Length==9)return Color.FromArgb(Convert.ToInt32(value.Substring(1,2),16),Convert.ToInt32(value.Substring(3,2),16),Convert.ToInt32(value.Substring(5,2),16),Convert.ToInt32(value.Substring(7,2),16));return ColorTranslator.FromHtml(value);}if(value.Contains(",")){var p=value.Split(',').Select(x=>int.Parse(x.Trim())).ToArray();return p.Length==4?Color.FromArgb(p[0],p[1],p[2],p[3]):Color.FromArgb(p[0],p[1],p[2]);}return Color.FromName(value);}catch{return Color.White;}}
  public static string BoundSuffix(JObject item){if(item["Unit"]!=null)return (string)item["Unit"]??"";string text=(string)item["Text"]??"",type=(string)item["TextType"]??"";return text.Length>0&&!string.Equals(text,type,StringComparison.OrdinalIgnoreCase)&&!System.Text.RegularExpressions.Regex.IsMatch(text,@"^\s*[+-]?\d")?text:"";}
  public static string BoundValue(JObject item,SensorSnapshot sensors){string type=(string)item["TextType"]??"",value=sensors.Get(type,"—"),unit=BoundSuffix(item);if(value=="—")return value;double number;if(double.TryParse(value,NumberStyles.Any,CultureInfo.InvariantCulture,out number)){if((type=="CPUTemp"||type=="GPUTemp")&&unit.Trim()=="°F")value=(number*9/5+32).ToString("0",CultureInfo.InvariantCulture);else if((type=="CpuFrequency"||type=="GpuFrequency")&&unit.Trim().Equals("GHz",StringComparison.OrdinalIgnoreCase))value=(number/1000).ToString("0.00",CultureInfo.InvariantCulture);}return value+unit;}
 }
}
